sect3.programlisting:
service imap-login {    
  inet_listener imaps {        
    port = 993        
    SSL = yes
  }
}

service auth {
  unix_listener /var/spool/postfix/private/auth {
    mode = 0660
    user = postfix        
    group = postfix  
  }
}

para.programlisting:
plugin { 
  fts = squat 
  fts_squat = partial=4 full=8
}

